"semi_supervised/confidence_filter": {
"path": "snippets/semi_supervised/confidence_filter.py",
"title": "Filter keyakinan dengan kuota per kelas",
"when": "Selalu bersama pseudo-label. Mencegah kelas mudah mendominasi.",
"avoid": "Satu threshold global tanpa kuota.",
"tags": "confidence kuota margin entropi out_of_scope",
"needs": [],
"code": "import numpy as np\n\ndef select_confident(p, threshold=.9, quota=None, margin=None):\n    \"\"\"Kembalikan indeks terpilih dan label. quota: maks per kelas.\"\"\"\n    p = np.asarray(p)\n    lab, conf = p.argmax(1), p.max(1)\n    ok = conf >= threshold\n    if margin is not None:\n        ok &= (np.sort(p, 1)[:, -1] - np.sort(p, 1)[:, -2]) >= margin\n    keep = []\n    for k in range(p.shape[1]):\n        ix = np.where(ok & (lab == k))[0]\n        ix = ix[np.argsort(-conf[ix])]\n        keep.append(ix[:quota] if quota else ix)\n    keep = np.sort(np.concatenate(keep))\n    return keep, lab[keep]\n\ndef entropy(p, eps=1e-12):\n    p = np.asarray(p)\n    return -(p * np.log(p + eps)).sum(1)\n\ndef reject_low(p, threshold=.5, other=-1):\n    \"\"\"Beri kelas 'lainnya' bila keyakinan rendah (out-of-scope).\"\"\"\n    return np.where(np.asarray(p).max(1) >= threshold, np.asarray(p).argmax(1), other)\n",
"valid": true
},
"semi_supervised/iterative_pseudo": {
"path": "snippets/semi_supervised/iterative_pseudo.py",
"title": "Pseudo-label berulang dengan penghentian",
"when": "Model cepat. Hentikan saat tidak melebihi noise floor pada gold.",
"avoid": "Transformer berulang: mahal.",
"tags": "iteratif pseudo stop",
"needs": [],
"code": "import numpy as np\nfrom sklearn.base import clone\nfrom sklearn.metrics import f1_score\n\ndef iterative_pseudo(vec, model, tr_t, tr_y, unl_t, gold_t, gold_y, rounds=3, threshold=.95, min_gain=.002):\n    \"\"\"gold: label asli yang tidak pernah dilatih. Kembalikan (vec, model, riwayat).\"\"\"\n    t, yy, hist, best = list(tr_t), np.asarray(tr_y), [], None\n    for r in range(rounds + 1):\n        v = clone(vec); m = clone(model)\n        m.fit(v.fit_transform(t), yy)\n        s = f1_score(gold_y, m.predict(v.transform(gold_t)), average=\"macro\")\n        hist.append(round(s, 4))\n        if best is not None and s < best[0] + min_gain:\n            break\n        best = (s, v, m)\n        if r == rounds:\n            break\n        p = m.predict_proba(v.transform(unl_t))\n        k = p.max(1) >= threshold\n        t, yy = list(tr_t) + [x for x, a in zip(unl_t, k) if a], np.r_[np.asarray(tr_y), m.classes_[p[k].argmax(1)]]\n    return best[1], best[2], hist\n",
"valid": true
},
"semi_supervised/pseudo_label": {
"path": "snippets/semi_supervised/pseudo_label.py",
"title": "Pseudo-label satu putaran",
"when": "Banyak unlabeled dan aturan mengizinkan. Evaluasi hanya pada label asli.",
"avoid": "Pseudo-label masuk validasi.",
"tags": "pseudo semi",
"needs": [],
"code": "import numpy as np\nfrom sklearn.base import clone\n\ndef pseudo_fit(vec, model, texts, y, unl_texts, threshold=.95):\n    \"\"\"Fit, ambil baris yakin, fit ulang. Kembalikan (vec, model, jumlah pseudo).\"\"\"\n    v = clone(vec); m = clone(model)\n    m.fit(v.fit_transform(texts), y)\n    p = m.predict_proba(v.transform(unl_texts))\n    keep = p.max(1) >= threshold\n    t2 = list(texts) + [t for t, k in zip(unl_texts, keep) if k]\n    y2 = np.r_[np.asarray(y), m.classes_[p[keep].argmax(1)]]\n    v2 = clone(vec); m2 = clone(model)\n    m2.fit(v2.fit_transform(t2), y2)\n    return v2, m2, int(keep.sum())\n",
"valid": true
},
